style.css:
@-moz-document domain("revisely.com") {
/* General body background and text */
  body, html {
    background-color: #121212 !important; /* Dark background */
    color: #e0e0e0 !important; /* Light text */
  }

  /* Links */
  a {
    color: #bb86fc !important; /* Purple links */
    text-decoration: none !important;
  }
  a:hover {
    color: #3700b3 !important; /* Darker purple for hover */
  }

  /* Headings */
  h1, h2, h3, h4, h5, h6 {
    color: #ffffff !important; /* Pure white headings */
  }

  /* Navbar */
  .navbar, .header, .top-bar, .menu-bar {
    background-color: #181818 !important; /* Dark navbar */
    color: #ffffff !important; /* White navbar text */
    border-bottom: 1px solid #333333 !important; /* Subtle border */
  }

  /* Buttons */
  button, .btn {
    background-color: #333333 !important; /* Dark gray buttons */
    color: #ffffff !important; /* White text */
    border: 1px solid #444444 !important; /* Subtle border */
  }
  button:hover, .btn:hover {
    background-color: #444444 !important; /* Lighter gray hover */
  }

  /* Input Fields */
  input, textarea, select {
    background-color: #222222 !important; /* Darker background */
    color: #e0e0e0 !important; /* Light text */
    border: 1px solid #555555 !important; /* Darker border */
  }
  input::placeholder, textarea::placeholder {
    color: #888888 !important; /* Gray placeholder text */
  }

  /* Cards and Panels */
  .card, .panel, .box, .content-section {
    background-color: #1e1e1e !important; /* Darker background for sections */
    color: #e0e0e0 !important; /* Light text */
    border: 1px solid #333333 !important; /* Subtle border */
    box-shadow: none !important; /* Remove shadows for flat design */
  }

  /* Tables */
  table {
    background-color: #1e1e1e !important; /* Dark table background */
    color: #e0e0e0 !important; /* Light text */
    border-collapse: collapse !important;
  }
  th, td {
    border: 1px solid #444444 !important; /* Darker borders */
    padding: 8px !important;
  }
  th {
    background-color: #222222 !important; /* Slightly darker for headers */
    color: #ffffff !important;
  }
  tr:nth-child(even) {
    background-color: #181818 !important; /* Alternate row color */
  }
  tr:nth-child(odd) {
    background-color: #1e1e1e !important;
  }

  /* Footer */
  .footer {
    background-color: #101010 !important; /* Very dark footer */
    color: #888888 !important; /* Gray text */
  }

  /* Modal and Popups */
  .modal, .popup {
    background-color: #222222 !important; /* Dark background for modals */
    color: #e0e0e0 !important; /* Light text */
    border: 1px solid #555555 !important; /* Darker border */
  }

  /* Tooltips */
  .tooltip {
    background-color: #333333 !important; /* Dark tooltip */
    color: #ffffff !important; /* White text */
    border: 1px solid #444444 !important; /* Subtle border */
  }

  /* Scrollbars */
  ::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }
  ::-webkit-scrollbar-track {
    background: #121212;
  }
  ::-webkit-scrollbar-thumb {
    background: #444444;
    border-radius: 5px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #555555;
  }

  /* Special sections (e.g., sidebar, widgets) */
  .sidebar, .widget, .right-panel, .left-panel {
    background-color: #181818 !important; /* Sidebar background */
    color: #e0e0e0 !important; /* Light text */
    border: 1px solid #333333 !important;
  }

  /* Notifications, Alerts, Badges */
  .alert, .notification, .badge {
    background-color: #2c2c2c !important; /* Darker notification */
    color: #ffffff !important;
    border: 1px solid #444444 !important;
  }

  /* Specific adjustments (if needed) */
  .highlighted, .selected, .active {
    background-color: #444444 !important; /* Highlight active elements */
    color: #ffffff !important;
  }
}
